import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"机器学习入门","description":"用直观例子理解监督学习、无监督学习、强化学习、数据集划分、过拟合、欠拟合与常见评估指标。","frontmatter":{"description":"用直观例子理解监督学习、无监督学习、强化学习、数据集划分、过拟合、欠拟合与常见评估指标。"},"headers":[],"relativePath":"ai/machine-learning.md","filePath":"ai/machine-learning.md","lastUpdated":1788693474000}'),l={name:"ai/machine-learning.md"};function n(o,a,s,d,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="机器学习入门" tabindex="-1">机器学习入门 <a class="header-anchor" href="#机器学习入门" aria-label="Permalink to &quot;机器学习入门&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 传统程序由人明确写出规则，机器学习则让模型从数据和反馈中拟合规律，再用这些规律处理新样本。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/ai/basics">AI 基础概念</a>，知道 AI、机器学习、深度学习和模型不是同一个概念。</li><li>不要求编程经验，也不需要先学概率论或微积分。</li><li>先接受一个基本边界：模型学到的是数据中的统计规律，不是永远正确的现实定律。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说明机器学习与传统规则程序的区别。</li><li>区分监督学习、无监督学习、强化学习和自监督学习。</li><li>解释特征、标签以及训练集、验证集、测试集的作用。</li><li>判断模型是否可能过拟合，并说明什么是泛化。</li><li>区分欠拟合与过拟合，说出几种常见对策。</li><li>解释交叉验证在什么场合有用、为什么不能替代测试集。</li><li>根据任务和错误代价选择基本评估指标。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="机器学习与传统程序有什么不同" tabindex="-1">机器学习与传统程序有什么不同 <a class="header-anchor" href="#机器学习与传统程序有什么不同" aria-label="Permalink to &quot;机器学习与传统程序有什么不同&quot;">​</a></h3><p>传统程序通常由开发者直接写出规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则 + 输入数据 -&gt; 输出结果</span></span></code></pre></div><p>例如，财务系统可以明确规定“订单金额乘以税率等于税额”。规则已知、边界清楚时，传统程序通常更可靠、更容易审计。</p><p>机器学习适合规则很难逐条写出的任务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>训练数据 + 学习算法 -&gt; 模型</span></span>
<span class="line"><span>模型 + 新输入 -&gt; 预测</span></span></code></pre></div><p>例如，垃圾邮件的写法不断变化，很难列出一组永不过期的规则。监督学习可以使用带有“垃圾邮件/正常邮件”答案的历史样本，让模型学习哪些输入模式与标签相关。</p><p>机器学习并不自动优于传统程序。实际系统经常把二者组合起来：模型负责识别复杂模式，程序负责权限、金额、合规和确定性规则。</p><h3 id="三种常见学习方式" tabindex="-1">三种常见学习方式 <a class="header-anchor" href="#三种常见学习方式" aria-label="Permalink to &quot;三种常见学习方式&quot;">​</a></h3><h4 id="监督学习-supervised-learning" tabindex="-1">监督学习（Supervised Learning） <a class="header-anchor" href="#监督学习-supervised-learning" aria-label="Permalink to &quot;监督学习（Supervised Learning）&quot;">​</a></h4><p>训练样本同时包含输入和正确答案，也就是标签。模型学习从特征到标签的映射。</p><ul><li>分类（Classification）：预测类别，例如垃圾邮件或正常邮件。</li><li>回归（Regression）：预测连续数值，例如房屋价格或用电量。</li></ul><h4 id="无监督学习-unsupervised-learning" tabindex="-1">无监督学习（Unsupervised Learning） <a class="header-anchor" href="#无监督学习-unsupervised-learning" aria-label="Permalink to &quot;无监督学习（Unsupervised Learning）&quot;">​</a></h4><p>数据没有预先给定的标签，模型尝试发现结构或相似性。</p><ul><li>聚类：把相似用户或文档分组。</li><li>降维：用更少的维度保留主要信息。</li><li>异常发现：寻找与大多数样本差异很大的数据点。</li></ul><p>聚类得到的组没有天然名称。模型只能指出“这些样本相似”，仍需要人结合业务判断每组代表什么。</p><h4 id="强化学习-reinforcement-learning" tabindex="-1">强化学习（Reinforcement Learning） <a class="header-anchor" href="#强化学习-reinforcement-learning" aria-label="Permalink to &quot;强化学习（Reinforcement Learning）&quot;">​</a></h4><p>一个智能体（Agent）在环境中采取动作，根据奖励或惩罚调整策略（Policy）。奖励可能延迟出现，因此模型需要考虑一系列动作的长期结果。</p><p>强化学习常用于游戏、机器人控制和序列决策。LLM 对齐中的部分方法也借用了强化学习思想，但“强化学习”不等于“让聊天模型多对话几次”。</p><p>奖励设计是强化学习最容易被低估的环节：奖励写歪了，模型会认真“钻空子”——这类现象常被叫做<strong>奖励钻空子（Reward Hacking）</strong>，达标手段背离初衷。经典例子来自清扫机器人：如果只要“没看见垃圾”就给奖励，机器人学会的捷径可能是关掉自己的摄像头——传感器里确实没有垃圾了，清扫的目标却完全落空。从规则看它每次都“达标”，从目标看已经失败。</p><p>也正因为奖励这么难写对，LLM 对齐中的 RLHF 才用人类偏好比较来代替手工奖励：与其猜“好回答该加多少分”，不如让人直接比较两个回答哪个更好。这条路线的展开见 <a href="/llm/training-alignment">训练、微调与对齐</a>。</p><p>除这三种之外，还有介于监督与无监督之间的自监督学习：从数据自身构造监督信号，让模型预测被遮住的部分，不需要人工打标签。大模型的预训练用的正是这一路，后面<a href="/llm/basics">大模型入门</a>会展开。</p><h3 id="特征、标签和样本" tabindex="-1">特征、标签和样本 <a class="header-anchor" href="#特征、标签和样本" aria-label="Permalink to &quot;特征、标签和样本&quot;">​</a></h3><ul><li><strong>样本（Example）</strong>：数据集中的一个实例，例如一封邮件。</li><li><strong>特征（Feature）</strong>：模型用于预测的输入信息，例如链接数量、主题词和发送时间。</li><li><strong>标签（Label）</strong>：监督学习希望模型预测的答案，例如“垃圾邮件”。</li></ul><p>特征多不代表效果一定更好。无关特征会增加噪声，泄漏答案的特征还可能让离线评估虚高。</p><h3 id="训练集、验证集和测试集" tabindex="-1">训练集、验证集和测试集 <a class="header-anchor" href="#训练集、验证集和测试集" aria-label="Permalink to &quot;训练集、验证集和测试集&quot;">​</a></h3><p>一份数据通常分成三个互不重叠的部分：</p><ol><li><strong>训练集（Training Set）</strong>：用于调整模型参数。</li><li><strong>验证集（Validation Set）</strong>：用于选择模型、特征、阈值和超参数。</li><li><strong>测试集（Test Set）</strong>：在方案基本确定后做最终检查，模拟从未见过的数据。</li></ol><p>如果反复根据测试集结果修改模型，测试集就间接参与了训练，评估会越来越乐观。这类问题属于数据泄漏（Data Leakage）的一种。</p><h3 id="交叉验证-小数据集的评估办法" tabindex="-1">交叉验证：小数据集的评估办法 <a class="header-anchor" href="#交叉验证-小数据集的评估办法" aria-label="Permalink to &quot;交叉验证：小数据集的评估办法&quot;">​</a></h3><p>数据太少、舍不得切出一块专门的验证集时，可以用 <strong>K 折交叉验证（K-Fold Cross-Validation）</strong>：把训练数据切成 K 份，每次用其中 1 份当验证集、其余 K−1 份训练，轮流 K 次，把 K 次的成绩取平均。比如 K=5：第 1 轮用第 1 份验证，第 2 轮换第 2 份，如此轮流，每个样本都恰好当过一次验证数据。</p><ul><li><strong>好处</strong>：评估不依赖某一次切分的运气，K 次平均比单次划分更稳定。</li><li><strong>代价</strong>：要完整训练 K 次，时间和算力乘以 K。</li><li><strong>适用</strong>：数据少、训练便宜的场合；数据量大或训练很贵时，一次简单划分通常就够。</li></ul><p>分类任务还有个常用变体：类别不平衡时用分层抽样切分，让每一折里各类别的比例都和整体一致，避免某一折恰好抽不到少数类、成绩大起大落。</p><p>注意它不能替代测试集：交叉验证始终在训练数据内部轮转，用途是选模型和比较<a href="/glossary#hyperparameter">超参数</a>；这些选择已经“用掉”了这批数据的评估信息。测试集仍要留到方案完全定下后做最终检查，这条规矩不因为用了交叉验证而改变。</p><h3 id="过拟合与泛化" tabindex="-1">过拟合与泛化 <a class="header-anchor" href="#过拟合与泛化" aria-label="Permalink to &quot;过拟合与泛化&quot;">​</a></h3><p>**过拟合（Overfitting）**是模型过度适应训练数据，连噪声和偶然细节也记住了。常见信号是：</p><ul><li>训练集表现继续变好。</li><li>验证集表现不再改善，甚至变差。</li><li>换到真实的新数据后错误明显增加。</li></ul><p>**泛化（Generalization）**是模型把训练中学到的规律正确应用到未见数据的能力。机器学习的目标不是把训练集背到满分，而是在代表真实场景的新样本上保持可接受表现。</p><h3 id="欠拟合-另一种失败" tabindex="-1">欠拟合：另一种失败 <a class="header-anchor" href="#欠拟合-另一种失败" aria-label="Permalink to &quot;欠拟合：另一种失败&quot;">​</a></h3><p>过拟合是“训练集学得太好”，反方向还有<strong>欠拟合（Underfitting）</strong>：模型太简单或训练太不充分，连训练集都学不好。信号正好相反：训练集表现差，验证集表现也差，两条曲线都停在低位。</p><p>对照着看：</p><ul><li><strong>过拟合</strong>：训练好、验证差——模型记住了训练细节，没学到可迁移的规律。</li><li><strong>欠拟合</strong>：训练和验证都差——模型根本没有足够的能力去抓住规律。</li></ul><p>一个具体画面：用一条直线去拟合明显弯曲的价格规律，无论训练多少轮，训练损失都压不下去——这就是典型的欠拟合；换成足够弯曲的曲线后训练损失降到很低，但验证损失反而回升——这就滑向了过拟合。</p><p>直觉上这是一对方向的偏差：模型太简单，学不到规律（偏差大）；模型对训练数据太敏感，把噪声当成了规律（方差大），换到新数据时两者的表现都会差，不必纠结公式，先记住“两种失败都要防”。实际训练中，先看训练集表现就能初判方向：训练集都学不好，先考虑加大模型能力、改进特征或延长训练，这时谈防止过拟合为时过早。</p><h3 id="过拟合的常见对策" tabindex="-1">过拟合的常见对策 <a class="header-anchor" href="#过拟合的常见对策" aria-label="Permalink to &quot;过拟合的常见对策&quot;">​</a></h3><p>发现验证表现开始变差，可以按代价从低到高尝试：</p><ul><li><strong>更多、更有代表性的数据</strong>：最直接的解法——见过的变化越多，越难靠背题得高分。注意“更多”之外还要“有代表性”，样本结构与真实场景脱节时，数量帮不上忙。</li><li><strong>简化模型</strong>：减少参数、减少层数，让模型容量与数据量匹配——模型小到记不下那些偶然细节，只能去学规律。</li><li><strong>正则化与早停</strong>：dropout、权重衰减、验证损失回升就停——这些手段在<a href="/ai/neural-networks">神经网络直觉</a>的“过拟合与正则化”一节展开，那页讲网络层面怎么防，本页只负责从数据和模型层面选。</li><li><strong>数据增强（Data Augmentation）</strong>：从现有样本造出合理的变体——图片翻转、裁剪、调亮度，文字的同义改写——相当于不重新采集就扩充了数据。</li></ul><p>对策没有万能顺序，但共同原则只有一个：把模型的努力从“记住训练集”引向“抓住可迁移的规律”。</p><h3 id="模型评估的基本概念" tabindex="-1">模型评估的基本概念 <a class="header-anchor" href="#模型评估的基本概念" aria-label="Permalink to &quot;模型评估的基本概念&quot;">​</a></h3><p>评估指标必须与任务目标和错误代价匹配。</p><ul><li><strong>准确率（Accuracy）</strong>：全部预测中有多少是正确的。类别严重不平衡时可能误导。</li><li><strong>精确率（Precision）</strong>：被模型判为正类的样本中，有多少真是正类。</li><li><strong>召回率（Recall）</strong>：所有真实正类中，有多少被模型找到了。</li><li><strong>F1</strong>：综合 Precision 和 Recall，适合需要平衡二者的场景。</li><li><strong>平均绝对误差（MAE）</strong>：回归任务中，预测值与真实值平均相差多少。</li><li><strong>损失（Loss）</strong>：训练时用于指导参数更新的目标，不一定等同于业务最终关心的指标。</li></ul><p>例如，疾病筛查通常更在意漏诊，因此会优先关注 Recall；垃圾邮件过滤如果误删正常邮件代价很高，就应重点关注 Precision 或假阳性率（正常邮件被误判成垃圾邮件的比例），而不能只看 Accuracy。</p><h2 id="最小推演-评估一个垃圾邮件分类器" tabindex="-1">最小推演：评估一个垃圾邮件分类器 <a class="header-anchor" href="#最小推演-评估一个垃圾邮件分类器" aria-label="Permalink to &quot;最小推演：评估一个垃圾邮件分类器&quot;">​</a></h2><p>假设测试集有 8 封邮件，模型结果如下（表中 TP=垃圾邮件判对、FN=垃圾邮件被漏判、TN=正常邮件判对、FP=正常邮件被误判）：</p><table tabindex="0"><thead><tr><th>实际情况</th><th style="text-align:right;">模型判断正确</th><th style="text-align:right;">模型判断错误</th></tr></thead><tbody><tr><td>垃圾邮件</td><td style="text-align:right;">3（TP）</td><td style="text-align:right;">1（FN）</td></tr><tr><td>正常邮件</td><td style="text-align:right;">3（TN）</td><td style="text-align:right;">1（FP）</td></tr></tbody></table><p>可以直接算出：</p><ul><li>Accuracy：<code>(3 + 3) / 8 = 75%</code></li><li>Precision：<code>3 / (3 + 1) = 75%</code></li><li>Recall：<code>3 / (3 + 1) = 75%</code></li></ul><p>三个数字恰好相同只是这个小例子的巧合。若 1000 封邮件中只有 10 封垃圾邮件，一个永远预测“正常”的模型也有 99% Accuracy，却完全没有识别垃圾邮件的能力。</p><p>这个推演不需要任何 API。它展示了评估的核心：先数清不同类型的正确和错误，再根据真实代价选择指标。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>把几种常见方法放在一张表里对比：</p><table tabindex="0"><thead><tr><th>方法</th><th>学习信号</th><th>典型输出</th><th>适合场景</th><th>主要风险</th></tr></thead><tbody><tr><td>传统规则程序</td><td>人写出的确定规则</td><td>精确计算或流程结果</td><td>税费、权限、协议校验</td><td>规则复杂时难维护</td></tr><tr><td>监督学习</td><td>带标签样本</td><td>类别或数值预测</td><td>分类、回归</td><td>标签偏差、过拟合</td></tr><tr><td>无监督学习</td><td>无标签数据的结构</td><td>聚类、低维表示</td><td>探索分组、发现相似性</td><td>结果未必有业务意义</td></tr><tr><td>强化学习</td><td>环境中的奖励或惩罚</td><td>动作策略</td><td>连续决策、控制</td><td>奖励设计错误、探索成本高</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“训练准确率高就是模型好”</strong>：需要看验证集、测试集和真实数据表现。</li><li><strong>“测试集可以反复调参”</strong>：频繁使用会让测试集失去独立性。</li><li><strong>“无监督学习会自动发现正确类别”</strong>：聚类只反映所用表示和距离下的相似性。</li><li><strong>“强化学习没有标签”</strong>：它没有逐样本标准答案，但有奖励信号。</li><li><strong>“指标越多越专业”</strong>：指标应服务于具体风险，不能回避错误代价。</li><li><strong>“模型学到了因果关系”</strong>：多数模型首先学到相关性，因果结论需要额外设计和证据。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么不能只保留训练集和测试集-然后反复用测试集选模型" tabindex="-1">1. 为什么不能只保留训练集和测试集，然后反复用测试集选模型？ <a class="header-anchor" href="#_1-为什么不能只保留训练集和测试集-然后反复用测试集选模型" aria-label="Permalink to &quot;1. 为什么不能只保留训练集和测试集，然后反复用测试集选模型？&quot;">​</a></h3><details><summary>查看答案</summary><p>因为每次根据测试结果修改模型，都把测试集信息泄漏进了开发过程。验证集用于日常选择和调参，测试集应在方案基本确定后做少量最终评估。</p></details><h3 id="_2-一个稀有事件分类器达到-99-accuracy-为什么仍可能没有价值" tabindex="-1">2. 一个稀有事件分类器达到 99% Accuracy，为什么仍可能没有价值？ <a class="header-anchor" href="#_2-一个稀有事件分类器达到-99-accuracy-为什么仍可能没有价值" aria-label="Permalink to &quot;2. 一个稀有事件分类器达到 99% Accuracy，为什么仍可能没有价值？&quot;">​</a></h3><details><summary>查看答案</summary><p>如果正类只占 1%，模型永远预测负类也能达到 99% Accuracy。还需要检查这类四格统计表（术语叫混淆矩阵）、Recall、Precision，以及漏报和误报的实际代价。</p></details><h3 id="_3-把没有标签的用户行为自动分成若干组-主要属于哪种学习方式" tabindex="-1">3. 把没有标签的用户行为自动分成若干组，主要属于哪种学习方式？ <a class="header-anchor" href="#_3-把没有标签的用户行为自动分成若干组-主要属于哪种学习方式" aria-label="Permalink to &quot;3. 把没有标签的用户行为自动分成若干组，主要属于哪种学习方式？&quot;">​</a></h3><details><summary>查看答案</summary><p>主要属于无监督学习中的聚类。分组结果只说明样本在当前特征表示下相似，组名和业务含义仍需人工解释。</p></details><h3 id="_4-一个模型在训练集上表现就很差-这是过拟合吗-更可能是什么" tabindex="-1">4. 一个模型在训练集上表现就很差，这是过拟合吗？更可能是什么？ <a class="header-anchor" href="#_4-一个模型在训练集上表现就很差-这是过拟合吗-更可能是什么" aria-label="Permalink to &quot;4. 一个模型在训练集上表现就很差，这是过拟合吗？更可能是什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>不是。过拟合的标志是训练好、验证差；训练集都学不好更可能是欠拟合——模型太简单、特征不足或训练不充分。先加大模型能力、改进特征或延长训练，把训练表现拉起来之后，才轮到讨论防止过拟合。</p></details><h3 id="_5-k-折交叉验证已经让每个样本都当过验证数据了-为什么还要单独留测试集" tabindex="-1">5. K 折交叉验证已经让每个样本都当过验证数据了，为什么还要单独留测试集？ <a class="header-anchor" href="#_5-k-折交叉验证已经让每个样本都当过验证数据了-为什么还要单独留测试集" aria-label="Permalink to &quot;5. K 折交叉验证已经让每个样本都当过验证数据了，为什么还要单独留测试集？&quot;">​</a></h3><details><summary>查看答案</summary><p>交叉验证始终在训练数据内部轮转，用途是选模型和比较超参数——这些选择已经“用掉”了这批数据的评估信息，它给出的成绩会偏乐观。测试集的职责是在方案完全定下后，用从未参与过任何选择的数据做最终检查；留到最后、只用少量次数，它才有资格代表“没见过的数据”。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/ai/basics">AI 基础概念</a>梳理 AI、机器学习、深度学习与模型的关系。</li><li><strong>同主题：</strong> <a href="/ai/neural-networks">神经网络直觉</a>往下拆一层，看模型怎样用权重和梯度调整参数。</li><li><strong>延伸方向：</strong> <a href="/llm/training-alignment">训练、微调与对齐</a>展示这些训练概念在大模型中的具体形态。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml" target="_blank" rel="noreferrer">Google：What is Machine Learning?</a>：Google 官方课程对机器学习定义的讲解页。</li><li><a href="https://developers.google.com/machine-learning/intro-to-ml/supervised" target="_blank" rel="noreferrer">Google：Supervised Learning</a>：监督学习与标签概念的官方讲解。</li><li><a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets" target="_blank" rel="noreferrer">Google：Training、Validation 与 Test Set</a>：三种数据集划分方式的官方说明。</li><li><a href="https://developers.google.com/machine-learning/crash-course/overfitting/overfitting" target="_blank" rel="noreferrer">Google：Overfitting</a>：过拟合现象与成因的官方讲解。</li><li><a href="https://developers.google.com/machine-learning/crash-course/classification/accuracy-precision-recall" target="_blank" rel="noreferrer">Google：Accuracy、Precision 与 Recall</a>：分类评估指标的官方讲解页。</li><li><a href="https://scikit-learn.org/stable/modules/cross_validation.html" target="_blank" rel="noreferrer">scikit-learn：Cross-validation: evaluating estimator performance</a>：K 折交叉验证的官方文档，含各种切分策略。</li><li><a href="https://arxiv.org/abs/1606.06565" target="_blank" rel="noreferrer">Amodei 等：Concrete Problems in AI Safety</a>：讨论奖励设计与奖励钻空子等安全问题的经典论文，清扫机器人的例子出自此处。</li></ul>`,87)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
